'use strict';
const fs=require('fs'),crypto=require('crypto'),z=require('zlib'),assert=require('assert/strict'),base=require('./publish-sheet-metadata.cjs');
const OP='sheet-authoritative-sync-20261105-v1',SHA='18d1ccb718beb40aa95ff63e53d3bd8c28896927faa8d3bc88a8492ae7e5a149',DIR='.sheet-sync-20261105';
function decode(a,k){assert.equal(a.operation,OP);assert.equal(a.sha256,SHA);const key=crypto.privateDecrypt({key:k,oaepHash:'sha256'},Buffer.from(a.key,'base64')),d=crypto.createDecipheriv('aes-256-gcm',key,Buffer.from(a.iv,'base64'));d.setAAD(Buffer.from(OP));d.setAuthTag(Buffer.from(a.tag,'base64'));const raw=z.gunzipSync(Buffer.concat([d.update(Buffer.from(a.data,'base64')),d.final()]));assert.equal(crypto.createHash('sha256').update(raw).digest('hex'),SHA);const p=JSON.parse(raw);assert.equal(p.entries.length,27341);assert.equal(new Set(p.entries.map(e=>e.id)).size,27341);const allowed=['title','artist','chordwiki','bpm','genre1','genre2','genre3','genre4','genre5','genre6','vocal_synths','release_year','anime_year','tieup','search','lyrics','composition','arrangement'];for(const e of p.entries){assert(/^[\w-]{1,80}$/.test(e.id));assert.deepEqual(Object.keys(e.values).sort(),[...allowed].sort());assert(Object.values(e.values).every(v=>typeof v==='string'));}return p;}
function patch(current,initial,desired){if(current==null)return null;const out={...current};let changed=false;for(const[f,v]of Object.entries(desired))if(base.value(current,f)===base.value(initial,f)&&base.value(current,f)!==v){out[f]=v;changed=true;}if(!changed)return;out._editRevision=Number(current._editRevision||0)+1;return out;}
async function main(){const{initializeApp,cert,deleteApp}=require('firebase-admin/app'),{getDatabase}=require('firebase-admin/database'),account=JSON.parse(process.env.FIREBASE_SERVICE_ACCOUNT),p=decode(JSON.parse(fs.readFileSync('maintenance/sheet-20261105.enc.json')),account.private_key),app=initializeApp({credential:cert(account),databaseURL:'https://kankan-session-room-default-rtdb.asia-southeast1.firebasedatabase.app'}),db=getDatabase(app);fs.mkdirSync(DIR,{recursive:true});try{
if(!process.argv.includes('--verify')){const initial=(await db.ref('songs').get()).val(),queue=p.entries.filter(e=>initial[e.id]&&Object.entries(e.values).some(([f,v])=>base.value(initial[e.id],f)!==v));fs.writeFileSync(DIR+'/before.enc.json',JSON.stringify(base.encryptAudit(queue.map(e=>({id:e.id,song:initial[e.id]})))));let cursor=0,updated=0;await Promise.all(Array.from({length:32},async()=>{while(cursor<queue.length){const e=queue[cursor++],tx=await db.ref('songs/'+e.id).transaction(s=>patch(s,initial[e.id],e.values),undefined,false);if(tx.committed)updated++;}}));if(updated)await db.ref('masterMeta/revision').set(db.ref('masterMeta').push().key);console.log('SYNC_APPLY '+JSON.stringify({sourceSongs:p.entries.length,changedSongs:queue.length,updatedSongs:updated}));
const core=require('../list-share-core.js'),master=(await db.ref('songs').get()).val(),shares=(await db.ref('publicListShares').get()).val()||{},changed=new Set(queue.map(e=>e.id));for(const token of Object.keys(shares)){if(!core.tokenOK(token))continue;await db.ref('publicListShares/'+token).transaction(s=>{if(!s)return null;if(s.reserved||!s.songs)return;let dirty=false;for(const[id,row]of Object.entries(s.songs)){if(!changed.has(id)||!master[id])continue;const value=core.song(master[id],{},{});if(!value)continue;for(const[f,v]of Object.entries(value))if(JSON.stringify(row[f])!==JSON.stringify(v)){row[f]=v;dirty=true;}}return dirty?s:undefined;},undefined,false);}return;}
const songs=(await db.ref('songs').get()).val(),missing=[],mismatches=[];let matched=0;for(const e of p.entries){if(!songs[e.id]){missing.push(e.id);continue;}for(const[f,v]of Object.entries(e.values))if(base.value(songs[e.id],f)===v)matched++;else mismatches.push({id:e.id,field:f});}const revision=(await db.ref('masterMeta/revision').get()).val(),search=(await db.ref('songSearchMeta').get()).val(),genres=(await db.ref('songGenreMeta').get()).val();assert.equal(search.sourceRevision,revision);assert.equal(genres.sourceRevision,revision);assert.equal(search.currentIndexKey,genres.currentIndexKey);const g=require('../genre-index-reader.js'),page=await g.page(db,genres.currentIndexKey,{genre1:'台湾'});assert(page.rows.length);assert(page.rows.every(r=>songs[r.id].genre1==='台湾'));for(const f of ['sort-master.js','song-genres.js']){const response=await fetch('https://kankan1176.com/'+f+'?sync='+OP);assert(response.ok);assert.equal(crypto.createHash('sha256').update(await response.text()).digest('hex'),crypto.createHash('sha256').update(fs.readFileSync(f)).digest('hex'));}const report={sourceSongs:p.entries.length,matchedCells:matched,missingSongs:missing.length,mismatchedCells:mismatches.length,indexCurrent:true,taiwanFilterHits:page.rows.length,publicAssetsVerified:true};fs.writeFileSync(DIR+'/verification.json',JSON.stringify(report));fs.writeFileSync(DIR+'/differences.enc.json',JSON.stringify(base.encryptAudit({missing,mismatches})));console.log('FINAL_VERIFICATION '+JSON.stringify(report));if(missing.length||mismatches.length){console.log('UNRESOLVED_PUBLIC_SONG_FIELDS '+JSON.stringify({missing,mismatches}));throw Error('Unresolved source differences');}
}finally{await deleteApp(app);}}
module.exports={decode,patch};if(require.main===module)main().catch(e=>{console.error(e.message);process.exitCode=1;});
